
const CATS = {"soul":{label:"Soul",desc:"Portraits of inner light",color:"#8b7bb5",paintings:[{src:"data:image/jpeg;base64,",title:"Prayer",medium:"Oil on canvas",cat:"soul"},{src:"data:image/jpeg;base64,",title:"Melody",medium:"Oil on canvas",cat:"soul"},{src:"data:image/jpeg;base64,",title:"Sages",medium:"Oil & gold leaf on canvas",cat:"soul"},{src:"data:image/jpeg;base64,",title:"Inner Light",medium:"Oil on canvas",cat:"soul"}]},"light":{label:"Light",desc:"Color as radiance",color:"#c9a84c",paintings:[{src:"data:image/jpeg;base64,",title:"Hummingbird",medium:"Oil on canvas",cat:"light"},{src:"data:image/jpeg;base64,",title:"Flower Garden",medium:"Oil & gold leaf on canvas",cat:"light"},{src:"data:image/jpeg;base64,",title:"Garden of Eden",medium:"Oil & gold leaf on canvas",cat:"light"},{src:"data:image/jpeg;base64,",title:"Bloom",medium:"Oil on canvas",cat:"light"}]},"story":{label:"Story",desc:"Sacred moments in time",color:"#6a9aaa",paintings:[{src:"data:image/jpeg;base64,",title:"Sinai Revelation",medium:"Oil on canvas",cat:"story"},{src:"data:image/jpeg;base64,",title:"Jerusalem of Gold",medium:"Oil & gold leaf on canvas",cat:"story"},{src:"data:image/jpeg;base64,",title:"The Wall",medium:"Oil on canvas",cat:"story"},{src:"data:image/jpeg;base64,",title:"Wedding",medium:"Oil & gold leaf on canvas",cat:"story"}]},};

// Ticker
const tickWords=['Soul','·','Light','·','Story','·','Oil on Canvas','·','Gold Leaf','·','Jewish Mysticism','·'];
const ti=document.getElementById('ticker-inner');
[...tickWords,...tickWords].forEach(w=>{const s=document.createElement('span');s.className=w==='·'?'ti ti-sep':'ti';s.textContent=w;ti.appendChild(s);});

// Hero slideshow
let hs=0; const sl=document.querySelectorAll('.hslide');
setInterval(()=>{sl[hs].classList.remove('active');hs=(hs+1)%sl.length;sl[hs].classList.add('active');},5500);

// Home cat cards
const hcats=document.getElementById('hcats');
Object.entries(CATS).forEach(([k,c])=>{
  const el=document.createElement('div'); el.className='hcat'; el.style.minHeight='340px';
  el.innerHTML=`<div class="hcat-img"><img src="${c.paintings[0].src}" alt="${c.label}" loading="lazy"></div>
  <div class="hcat-body">
    <div class="hcat-en">${c.label}</div>
    <div class="hcat-desc">${c.desc}</div>
    <span class="hcat-cta">Explore →</span>
  </div>`;
  el.onclick=()=>{showPage('gallery');setTimeout(()=>galEnterCat(k),20);};
  hcats.appendChild(el);
});

// Home cat-title-row
const ctRow=document.getElementById('cat-titles');
Object.entries(CATS).forEach(([k,c])=>{
  const card=document.createElement('div'); card.className='cat-title-card';
  card.innerHTML=`<div class="cat-title-en">${c.label}</div>
  <div class="cat-title-desc">${c.desc}</div>
  <div class="cat-title-img"><img src="${c.paintings[1]?.src||c.paintings[0].src}" alt="${c.label}" loading="lazy"></div>`;
  card.onclick=()=>{showPage('gallery');setTimeout(()=>galEnterCat(k),20);};
  ctRow.appendChild(card);
});

// Nav
const navEl=document.getElementById('nav');
function setNav(id){
  if(id==='gallery'||id==='about-page') navEl.className='solid';
  else navEl.className='over';
}
window.addEventListener('scroll',()=>{
  if(document.getElementById('home').classList.contains('active'))
    navEl.className=window.scrollY>80?'solid':'over';
},{passive:true});

// Pages
const navMap={home:'nb-home',gallery:'nb-gallery','about-page':'nb-about','contact-page':'nb-about'};
function showPage(id){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('.nb').forEach(b=>b.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  document.getElementById(navMap[id])?.classList.add('active');
  window.scrollTo(0,0);
  setNav(id);
  if(id==='gallery'){
    document.getElementById('gal-picker').style.display='flex';
    const gv=document.getElementById('gal-grid-view');
    if(gv) gv.style.display='none';
  }
  document.querySelectorAll('.rev').forEach(el=>revObs.observe(el));
}

// ── Gallery ──
const GAL_CATS = {"soul":{label:"Soul",desc:"Portraits of inner light",cover:"data:image/jpeg;base64,",paintings:[{src:"data:image/jpeg;base64,",title:"Prayer",medium:"Oil on canvas"},{src:"data:image/jpeg;base64,",title:"Melody",medium:"Oil on canvas"},{src:"data:image/jpeg;base64,",title:"Sages",medium:"Oil & gold leaf on canvas"},{src:"data:image/jpeg;base64,",title:"Inner Light",medium:"Oil on canvas"}]},"light":{label:"Light",desc:"Color as radiance",cover:"data:image/jpeg;base64,",paintings:[{src:"data:image/jpeg;base64,",title:"Hummingbird",medium:"Oil on canvas"},{src:"data:image/jpeg;base64,",title:"Flower Garden",medium:"Oil & gold leaf on canvas"},{src:"data:image/jpeg;base64,",title:"Garden of Eden",medium:"Oil & gold leaf on canvas"},{src:"data:image/jpeg;base64,",title:"Bloom",medium:"Oil on canvas"}]},"story":{label:"Story",desc:"Sacred moments in time",cover:"data:image/jpeg;base64,",paintings:[{src:"data:image/jpeg;base64,",title:"Sinai Revelation",medium:"Oil on canvas"},{src:"data:image/jpeg;base64,",title:"Jerusalem of Gold",medium:"Oil & gold leaf on canvas"},{src:"data:image/jpeg;base64,",title:"The Wall",medium:"Oil on canvas"},{src:"data:image/jpeg;base64,",title:"Wedding",medium:"Oil & gold leaf on canvas"}]},};
let galCat = 'soul';

function galEnterCat(cat) {
  galCat = cat;
  document.getElementById('gal-picker').style.display = 'none';
  document.getElementById('gal-grid-view').style.display = 'block';
  buildGalTabs();
  buildGalGrid();
  window.scrollTo(0, 0);
}

function galBack() {
  document.getElementById('gal-grid-view').style.display = 'none';
  document.getElementById('gal-picker').style.display    = 'flex';
  window.scrollTo(0, 0);
}

function buildGalTabs() {
  const row = document.getElementById('gal-tab-row');
  row.innerHTML = '';
  Object.entries(GAL_CATS).forEach(([k, c]) => {
    const b = document.createElement('button');
    b.textContent = c.label;
    b.style.cssText = 'background:none;border:none;border-bottom:2px solid transparent;cursor:pointer;font-family:"EB Garamond",serif;font-size:1rem;font-style:italic;font-weight:400;color:var(--light);padding:0 1.4rem;height:50px;margin-bottom:-1px;transition:color .25s,border-color .25s;letter-spacing:.04em;';
    if (k === galCat) { b.style.color = 'var(--ink)'; b.style.borderBottomColor = 'var(--gold)'; }
    b.onmouseover = () => { if(k!==galCat) b.style.color='var(--muted)'; };
    b.onmouseout  = () => { if(k!==galCat) b.style.color='var(--light)'; };
    b.onclick = () => {
      if (k === galCat) return;
      galCat = k;
      buildGalTabs();
      buildGalGrid();
    };
    row.appendChild(b);
  });
}

function buildGalGrid() {
  const cat = GAL_CATS[galCat];
  document.getElementById('gal-heading').textContent  = cat.label;
  document.getElementById('gal-subdesc').textContent  = cat.desc;
  const grid = document.getElementById('gal-grid');
  grid.innerHTML = '';
  cat.paintings.forEach((p, i) => {
    const el = document.createElement('div');
    el.style.cssText = 'background:var(--white);overflow:hidden;cursor:pointer;position:relative;aspect-ratio:4/5;';
    el.innerHTML = `
      <img src="${p.src}" alt="${p.title}" loading="${i<3?'eager':'lazy'}"
        style="width:100%;height:100%;object-fit:cover;display:block;transition:transform .65s cubic-bezier(.25,.46,.45,.94),filter .4s;filter:brightness(.92);"
        onmouseover="this.style.transform='scale(1.05)';this.style.filter='brightness(1)'"
        onmouseout="this.style.transform='';this.style.filter='brightness(.92)'">
      <div class="gg-cap" style="position:absolute;bottom:0;left:0;right:0;padding:1.1rem 1rem .85rem;background:linear-gradient(to top,rgba(26,23,20,.82) 0%,transparent 100%);opacity:0;transition:opacity .3s;">
        <div style="font-family:'EB Garamond',serif;font-size:1rem;font-style:italic;color:#fff;">${p.title}</div>
        <div style="font-size:.6rem;color:rgba(255,255,255,.6);letter-spacing:.08em;text-transform:uppercase;margin-top:.12rem;">${p.medium}</div>
      </div>`;
    el.querySelector('img').onmouseover = function() {
      this.style.transform='scale(1.05)'; this.style.filter='brightness(1)';
      el.querySelector('.gg-cap').style.opacity='1';
    };
    el.querySelector('img').onmouseout = function() {
      this.style.transform=''; this.style.filter='brightness(.92)';
      el.querySelector('.gg-cap').style.opacity='0';
    };
    el.onclick = () => galOpenLB(i);
    grid.appendChild(el);
  });
}

// Lightbox for gallery
let galLBIdx = 0;
function galOpenLB(i) {
  galLBIdx = i;
  const p = GAL_CATS[galCat].paintings[i];
  document.getElementById('lb-img').src = p.src;
  document.getElementById('lb-cap').textContent = p.title + ' · ' + p.medium;
  document.getElementById('lb').classList.add('open');
}
function lbNav(dir) {
  const len = GAL_CATS[galCat].paintings.length;
  galLBIdx = (galLBIdx + dir + len) % len;
  const p = GAL_CATS[galCat].paintings[galLBIdx];
  document.getElementById('lb-img').src = p.src;
  document.getElementById('lb-cap').textContent = p.title + ' · ' + p.medium;
}

document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeLB();
  if (document.getElementById('lb').classList.contains('open')) {
    if (e.key === 'ArrowRight') lbNav(1);
    if (e.key === 'ArrowLeft')  lbNav(-1);
  }
});
let _tx = null;
document.addEventListener('touchstart', e => { _tx = e.touches[0].clientX; });
document.addEventListener('touchend', e => {
  if (_tx === null) return;
  const dx = e.changedTouches[0].clientX - _tx; _tx = null;
  if (!document.getElementById('lb').classList.contains('open')) return;
  if (Math.abs(dx) < 40) return;
  lbNav(dx < 0 ? 1 : -1);
});

function submitContact(e){
  e.preventDefault();
  const mailto = 'mailto:art@yehudis.com?subject=Enquiry from website&body='
    + encodeURIComponent(document.getElementById('cp-name').value + ' writes:\n\n' + document.getElementById('cp-msg').value);
  window.location.href = mailto;
  document.getElementById('cp-success').classList.add('show');
  e.target.reset();
}
function closeLB(){document.getElementById('lb').classList.remove('open');}
document.getElementById('lb').addEventListener('click',e=>{if(e.target.id==='lb')closeLB();});

const revObs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('vis');});},{threshold:0.1});
document.querySelectorAll('.rev').forEach(el=>revObs.observe(el));
setNav('home');
